/* CNC Handbook: common non-ferrous alloys and cast irons, normative sources and independent cutting commentary. */
(()=>{'use strict';const d=window.CNC_DATA;if(!d)return;Object.assign(d.sources,{"grade-gost4784":{"name":"Росстандарт — ГОСТ 4784-2019, деформируемые Al-сплавы","url":"https://protect.gost.ru/gost/details/ec049aa0-9abc-406e-be53-2fcae00b74ef","details":"Марки и химический состав деформируемых алюминиевых сплавов; свойства конкретного состояния и сортамента проверяются отдельно."},"grade-gost1583":{"name":"Росстандарт — ГОСТ 1583-93, литейные Al-сплавы","url":"https://protect.gost.ru/gost/details/404ae642-6b30-451b-b215-22860d4e2b38","details":"Марки и состав литейных алюминиевых сплавов; состав отливки не определяет напрямую возможный режим резания."},"grade-gost19807":{"name":"Росстандарт — ГОСТ 19807-91, титан и деформируемые титановые сплавы","url":"https://protect.gost.ru/gost/details/ecc4dd16-d27c-4f70-ac8b-f89ce5943f5f","details":"Марки технического титана и титановых сплавов"},"grade-gost1412":{"name":"Росстандарт — ГОСТ 1412-85, серый чугун с пластинчатым графитом","url":"https://protect.gost.ru/gost/details/cb7d4cf2-4a02-416e-a751-60e5bd998e03","details":"Классификация марок серого чугуна по требованиям к механическим свойствам"},"grade-gost7293":{"name":"Росстандарт — ГОСТ 7293-85, высокопрочный чугун с шаровидным графитом","url":"https://protect.gost.ru/gost/details/93b96880-c3b5-46e7-a8a2-f429a48edae7","details":"Марки высокопрочных чугунов и требования к изделиям"},"grade-gost859":{"name":"Росстандарт — ГОСТ 859-2014, медь","url":"https://protect.gost.ru/gost/details/8b09dfe4-609d-4813-9894-e66ab3f382ba","details":"Марки меди и химический состав"},"grade-gost15527":{"name":"Росстандарт — ГОСТ 15527-2004, латуни","url":"https://protect.gost.ru/gost/details/94e1e708-b830-44d1-a948-87e9d196270c","details":"Марки деформируемых медно-цинковых сплавов и состав"},"grade-gost18175":{"name":"Росстандарт — ГОСТ 18175-78, безоловянные бронзы","url":"https://protect.gost.ru/gost/details/5184c82d-37fc-4d70-af9a-33908fb3158d","details":"Деформируемые безоловянные бронзы, включая алюминиево-железные"}});d.materialGradeAtlas=d.materialGradeAtlas||[];const grades=[{"id":"mat-grade-alloy-01","name":"Д16Т","family":"aluminium","group":"Алюминий","subgroup":"Алюминиевые сплавы","std":"ГОСТ 4784-2019, деформируемые Al-сплавы","source":"grade-gost4784","overview":"Дюралюминий Al–Cu–Mg в закалённом и естественно состаренном состоянии. Д16 — отдельная марка сплава, Т — состояние после закалки и естественного старения; корректное написание именно Д16Т, не «ДТ16». Похожие по химии зарубежные 2024 не являются автоматической заменой без сопоставления состояний и требований.","state":"Механические свойства зависят от формы проката, толщины и термообработки; на массивной плите возможно перераспределение остаточных напряжений при снятии карманов.","behavior":"В сравнении с мягким алюминием может формировать более дробную стружку, но условия налипания и устойчивости зависят от кромки. У тонких элементов важны зажим и прогиб.","tool":"Острая геометрия под Al, равномерные припуски, хорошее удаление стружки и контроль деформации после снятия зажима.","risk":"Увод плоскостности плиты; задиры при наросте; деформация тонких стенок; повреждение слоя при небрежном захвате.","checks":"Проверить именно Д16Т, не Д16М; вид полуфабриката, состояние и качество поверхности; ожидаемую деформацию после черновой.","link":"mat-grade-alloy-01","linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-02","name":"АМг6","family":"aluminium","group":"Алюминий","subgroup":"Алюминиевые сплавы","std":"ГОСТ 4784-2019, деформируемые Al-сплавы","source":"grade-gost4784","overview":"Алюминиево-магниевый деформируемый сплав. АМг6 — относительно высоколегированный магнием деформируемый алюминиевый сплав, широко используемый в сварных и коррозионностойких конструкциях.","state":"В отличие от Д16Т, прочность связана с твёрдым раствором и обработкой давлением, а не с тем же механизмом закалки и старения. После холодной деформации свойства могут отличаться.","behavior":"Пластичный материал способен активно налипать и создавать длинную стружку; тепловые и зажимные деформации влияют на точность больших деталей.","tool":"Особое внимание удели чистой острой кромке, полированным канавкам, отведению вязкой стружки и предотвращению повторного резания.","risk":"Нарост, матовые задиры, заусенцы на выходе и коробление тонких листов.","checks":"Состояние проката, толщина, зажим и потребность в сварке или коррозионной стойкости.","link":"mat-grade-alloy-02","linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-03","name":"АМг3","family":"aluminium","group":"Алюминий","subgroup":"Алюминиевые сплавы","std":"ГОСТ 4784-2019, деформируемые Al-сплавы","source":"grade-gost4784","overview":"Алюминиево-магниевый сплав средней степени легирования. Часто применяется в листах, корпусных и сварных конструкциях, где важны пластичность и устойчивость к коррозии.","state":"Мягкие или нагартованные состояния отличаются по жёсткости и формообразованию. Одно имя АМг3 не заменяет обозначение состояния поставки.","behavior":"Для мягких листов характерны заусенцы, размазывание и чувствительность к опорам. Механические свойства после деформации отличаются от термически упрочняемых Al–Cu–Mg.","tool":"Не делай длинный вылет фрезы без необходимости; крепи большие тонкие поверхности с минимальной деформацией.","risk":"Смазывание поверхности, длинная стружка, прогиб и зависимость размера от снятия прижимов.","checks":"Состояние листа, способ фиксации, открытые тонкие стенки, характер удаления стружки.","link":"mat-grade-alloy-03","linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-04","name":"АД31","family":"aluminium","group":"Алюминий","subgroup":"Алюминиевые сплавы","std":"ГОСТ 4784-2019, деформируемые Al-сплавы","source":"grade-gost4784","overview":"Деформируемый Al–Mg–Si для профилей. АД31 широко встречается как прессованный алюминиевый профиль. При термообработке и старении свойства меняются; сам по себе он не равен Д16 или В95.","state":"В поставке встречаются разные состояния и варианты с различной прочностью, а на профилях могут быть тонкие полки и остаточные напряжения от прессования.","behavior":"Чистовой проход по тонкой полке часто ограничен не мощностью шпинделя, а её прогибом и налипанием на режущей кромке.","tool":"Поддерживай полки, исключай сильный сжим профиля тисками, проверяй геометрию после разжима и острый инструмент под Al.","risk":"Вмятины от крепежа, вибрация полки и разница измерений в закреплённом и свободном положении.","checks":"Конкретный профиль и состояние старения; толщина стенок, качество базы, наличие анодирования.","link":"mat-grade-alloy-04","linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-05","name":"В95","family":"aluminium","group":"Алюминий","subgroup":"Алюминиевые сплавы","std":"ГОСТ 4784-2019, деформируемые Al-сплавы","source":"grade-gost4784","overview":"Высокопрочный деформируемый Al–Zn–Mg–Cu сплав. В95 — высокопрочный алюминиевый сплав, применяемый в нагруженных деталях. Состав и обозначение состояния отличают его от Д16Т и АМг6.","state":"При различной закалке и искусственном старении прочность и напряжённое состояние отличаются; особенно важно не путать В95 и В95Т1.","behavior":"Силовая нагрузка и износ инструмента могут оказаться выше, чем при фрезеровании мягкого алюминия; толстые плиты чувствительны к балансировке снятия.","tool":"Смотри состояние в сертификате, выбирай подходящую кромку и стратегию черновой, оставляй обоснованный припуск до чистовой после оценки коробления.","risk":"Увод тонкого контура после черновой, микросколы от неравномерного остатка, изменение размера от нагрева.","checks":"Данные по состоянию, толщина плиты, требования к коррозии и остаточным напряжениям.","link":"mat-grade-alloy-05","linked":["mat-stress","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-06","name":"АК12 (АЛ2)","family":"aluminium-cast","group":"Алюминий","subgroup":"Литейные алюминиевые сплавы","std":"ГОСТ 1583-93, литейные Al-сплавы","source":"grade-gost1583","overview":"Литейный алюминиево-кремниевый сплав, силумин. АК12 (в прежнем обозначении АЛ2) содержит существенную долю кремния; структура и форма кремниевых частиц делают поведение отличным от деформируемого алюминия.","state":"Свойства зависят от способа литья, модификации и пористости. Даже на одной отливке корка и сердцевина могут различаться.","behavior":"Твёрдые частицы кремния ускоряют абразивный износ, а вскрытые поры нарушают гладкость финишной поверхности.","tool":"Для массовой обработки абразивных Al–Si возможны стойкие кромки и PCD по каталогу; учитывай литейную корку и локальные изменения припуска.","risk":"Абразивный износ, непрогнозируемый скол на включениях, поры и раковины после чистовой.","checks":"Вид отливки, процент Si по документу, корка, пористость и требования к внешнему виду.","link":"mat-grade-alloy-06","linked":["mat-al-si","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-07","name":"ВТ1-0","family":"titanium","group":"Титан","subgroup":"Титан и титановые сплавы","std":"ГОСТ 19807-91, титан и деформируемые титановые сплавы","source":"grade-gost19807","overview":"Технически чистый титан. ВТ1-0 — технический титан с высокой коррозионной стойкостью; не является аналогом по прочности сплава ВТ6.","state":"Сплав не должен описываться как высокопрочный закалённый ВТ6. Состояние проката и деформации влияет на пластичность и твёрдость поверхности.","behavior":"При сравнительно небольшой прочности сохраняются характерные для титана низкая теплопроводность, вязкость стружки и адгезия при контакте с кромкой.","tool":"Выбирай геометрию и охлаждение именно для технического титана; обеспечь эвакуацию стружки и достаточно жёсткую сборку.","risk":"Налипание, задиры, нагрев кромки и местная деформация мягкого заготовочного слоя.","checks":"Марка ВТ1-0 vs ВТ6, состояние поставки, фактическая прочность, правила пожарной безопасности для стружки.","link":"mat-grade-alloy-07","linked":["mat-titanium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-08","name":"ВТ6","family":"titanium","group":"Титан","subgroup":"Титан и титановые сплавы","std":"ГОСТ 19807-91, титан и деформируемые титановые сплавы","source":"grade-gost19807","overview":"Двухфазный титановый сплав Ti–Al–V. ВТ6 — титановый сплав альфа+бета; зарубежные Grade 5/Ti-6Al-4V близки по классу, но прямую замену утверждают только по стандарту и состоянию.","state":"Закалка и старение либо другой заданный режим могут значительно менять прочность, а сложные детали после обработки способны иметь остаточные напряжения.","behavior":"Сочетание высокой удельной прочности, неблагоприятного отвода тепла и упругой податливости тонких стенок затрудняет фрезерование.","tool":"Используй допустимые каталожные режимы для конкретного сплава, устойчивую фиксацию и контролируемое охлаждение; на сложной 3D-форме оцени локальное ae.","risk":"Перегрев, ускоренный износ, скол, вибрации тонких стенок, риск воспламенения мелкой стружки.","checks":"Состояние и свойства, длина свободного вылета, условия СОЖ, процедура безопасной уборки стружки.","link":"mat-grade-alloy-08","linked":["mat-titanium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-09","name":"ОТ4-1","family":"titanium","group":"Титан","subgroup":"Титан и титановые сплавы","std":"ГОСТ 19807-91, титан и деформируемые титановые сплавы","source":"grade-gost19807","overview":"Титановый сплав системы Ti–Al–Mn. ОТ4-1 относят к группе деформируемых титановых сплавов с алюминием и марганцем. Поведение не равно ВТ1-0 и ВТ6.","state":"Формирование структуры и свойства определяются термомеханической обработкой; толщину и состояние полуфабриката проверяют отдельно.","behavior":"Для резания остаются характерны тепло и адгезия титана, но конкретная прочность и механика стружки отличаются от ВТ6.","tool":"Не подставляй режимы ВТ6 «по умолчанию»; сверь марку, состояние, каталог инструмента и твёрдость.","risk":"Налипание, термический износ, деформация тонких стенок, опасная мелкая стружка.","checks":"Сертификат ОТ4-1, состояние термообработки, режим охлаждения и безопасность обращения со стружкой.","link":"mat-grade-alloy-09","linked":["mat-titanium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-10","name":"СЧ20","family":"cast-iron","group":"Чугуны","subgroup":"Чугуны","std":"ГОСТ 1412-85, серый чугун с пластинчатым графитом","source":"grade-gost1412","overview":"Серый чугун с пластинчатым графитом. Марка обозначает класс свойств чугуна с пластинчатым графитом, а не точный химический состав отливки. Часто встречается в корпусах и станочных деталях.","state":"Структура металлической матрицы и качество литья меняют твёрдость; литейная корка, песок и включения отличаются от сердцевины.","behavior":"При подходящих условиях образует короткую стружку, но корка и включения дают ударный контакт и абразивный износ.","tool":"Используй инструмент для группы K с учётом отливки; на первом проходе проверь корку и безопасность подхода, при чистовой — качество матрицы.","risk":"Абразивный износ, локальный скол на песке, пыль и поры поверхности.","checks":"Марка и класс прочности, реальная твёрдость, размеры/припуск отливки, требования к удалению пыли.","link":"mat-grade-alloy-10","linked":["mat-cast-iron","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-11","name":"СЧ25","family":"cast-iron","group":"Чугуны","subgroup":"Чугуны","std":"ГОСТ 1412-85, серый чугун с пластинчатым графитом","source":"grade-gost1412","overview":"Серый чугун более высокого класса прочности. СЧ25 — серый чугун с пластинчатым графитом, отличающийся классом механических требований от СЧ20. Не универсально «твёрже на 25%».","state":"На фактическую обрабатываемость влияет металлическая матрица: перлитность, охлаждение и допустимые дефекты отливки.","behavior":"При более прочной матрице средняя нагрузка может измениться, а характер износа всё ещё сильно определяется коркой и включениями.","tool":"Не используй только обозначение СЧ25 для назначения Vc; уточняй отливку, структуру и рекомендацию подгруппы ISO K.","risk":"Износ по задней поверхности, повреждение зуба на твёрдом включении, нестабильная шероховатость.","checks":"СЧ20 vs СЧ25 в техдокументации, матрица, твёрдость, корка и заданная точность.","link":"mat-grade-alloy-11","linked":["mat-cast-iron","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-12","name":"ВЧ50","family":"cast-iron","group":"Чугуны","subgroup":"Чугуны","std":"ГОСТ 7293-85, высокопрочный чугун с шаровидным графитом","source":"grade-gost7293","overview":"Высокопрочный чугун с шаровидным графитом. ВЧ50 — высокопрочный чугун, где форма графита обычно шаровидная, а не пластинчатая, как у СЧ20/СЧ25. Марка связана с требованиями механических свойств.","state":"Свойства зависят от ферритно-перлитной структуры, режима производства и возможной термообработки отливки.","behavior":"Может давать другую стружку и другие силы по сравнению с серым чугуном; нельзя автоматически назначать режим СЧ20.","tool":"Сверь подгруппу группы K, твёрдость, матрицу и первый припуск; на конечной поверхности контролируй включения и поры.","risk":"Рваная стружка и более высокие силы при определённой матрице, абразивный износ, прерывистый контакт.","checks":"Марка ВЧ50 и матрица, требования к отливке, HBW, характер стружки.","link":"mat-grade-alloy-12","linked":["mat-cast-iron","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-13","name":"М1","family":"copper","group":"Медные сплавы","subgroup":"Медь","std":"ГОСТ 859-2014, медь","source":"grade-gost859","overview":"Медь высокой чистоты. М1 — марка меди, часто используемая в электротехнических и теплопроводных деталях. Это не бронза и не латунь.","state":"Состояние после отжига или нагартовки существенно меняет пластичность и твёрдость, но материал остаётся относительно вязким и склонным к деформации.","behavior":"При фрезеровании мягкой меди возможны длинная стружка, залипание и сильные заусенцы. Зажим легко повреждает чистовую поверхность.","tool":"Особое внимание к остроте режущей кромки, эвакуации стружки и исключению повреждения мягких баз зажимами.","risk":"Заусенцы, смятая кромка, местные задиры и вмятины от оснастки.","checks":"Состояние поставки, требование к электропроводности, температура детали и способ закрепления.","link":"mat-grade-alloy-13","linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-14","name":"Л63","family":"brass","group":"Медные сплавы","subgroup":"Латуни","std":"ГОСТ 15527-2004, латуни","source":"grade-gost15527","overview":"Двухкомпонентная латунь Cu–Zn. Л63 — деформируемая латунь с основой из меди и цинка, без того же назначения свинцовых добавок, что у ЛС59-1.","state":"После отжига или нагартовки свойства и форма стружки отличаются. Различия с ЛС59-1 важно учитывать до выбора инструмента.","behavior":"Вязкость и склонность к заусенцам может быть выше, чем у автоматной свинцовой латуни; характер стружки зависит от состояния.","tool":"Используй подходящую геометрию для латуни; контролируй зажим и не оставляй тонкие упругие полки без поддержки.","risk":"Заусенцы и вмятины на поверхности, вибрация тонких стенок, неравномерная стружка.","checks":"Уточнить Л63 vs ЛС59-1, состояние проката и требования к поверхности.","link":"mat-grade-alloy-14","linked":["mat-material-selection","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-15","name":"ЛС59-1","family":"brass","group":"Медные сплавы","subgroup":"Латуни","std":"ГОСТ 15527-2004, латуни","source":"grade-gost15527","overview":"Свинцовая автоматная латунь. ЛС59-1 — медно-цинковая латунь со свинцом, который заметно меняет разрушение стружки. Сочетание букв ЛС важно: не путать с Л63.","state":"После обработки давлением свойства отличаются, а присутствие свинца влияет на формирование короткой стружки и назначение материала.","behavior":"В подходящих условиях часто даёт более короткую стружку и легче автоматизируется, чем многие бессвинцовые латуни; профиль и состояние влияют на результат.","tool":"Подбор геометрии для латуни отличается от мягкого алюминия. Соблюдай правила обращения со стружкой, содержащей свинец.","risk":"Вкрапления и ухудшение поверхности при неподходящей кромке; вредная пыль и загрязнённая стружка.","checks":"Свинцовая ли марка, наличие требований к контакту с пищевой продукцией/питьевой водой, правила обращения с отходами.","link":"mat-grade-alloy-15","linked":["mat-material-selection","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-16","name":"БрАЖ9-4","family":"bronze","group":"Медные сплавы","subgroup":"Бронзы","std":"ГОСТ 18175-78, безоловянные бронзы","source":"grade-gost18175","overview":"Алюминиево-железная безоловянная бронза. БрАЖ9-4 — бронза системы Cu–Al–Fe с повышенной прочностью в сравнении со многими мягкими медными сплавами. Не равнозначна ЛС59-1 по обрабатываемости.","state":"Структура и состояния после деформации либо термообработки существенно влияют на твёрдость, а у некоторых условий возможна неоднородность фаз.","behavior":"По сравнению с мягкой медью нагрузка на кромку может быть выше, а устойчивый проход важнее максимальной скорости. Работа по корке также отличается.","tool":"Подбирай инструмент по группе и конкретной твёрдости; избегай скачков радиального зацепления в углах.","risk":"Повышенный износ и локальные сколы при прерывистом входе; ухудшение поверхности из-за биения.","checks":"Состояние, стандарт, фактическая твёрдость, тип заготовки и конкретная оснастка.","link":"mat-grade-alloy-16","linked":["mat-material-selection","mat-iso-groups","mat-material-selection"]}];const articles=[{"id":"mat-grade-alloy-01","cat":"materials","title":"Д16Т — свойства и особенности фрезерования","subtitle":"Алюминиевые сплавы","quick":"Дюралюминий Al–Cu–Mg в закалённом и естественно состаренном состоянии. Д16 — отдельная марка сплава, Т — состояние после закалки и естественного старения; корректное написание именно Д16Т, не «ДТ16». Похожие по химии зарубежные 2024 не являются автоматической заменой без сопоставления состояний и требований.","tags":["Д16Т","Д16Т","Алюминиевые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Дюралюминий Al–Cu–Mg в закалённом и естественно состаренном состоянии. Д16 — отдельная марка сплава, Т — состояние после закалки и естественного старения; корректное написание именно Д16Т, не «ДТ16». Похожие по химии зарубежные 2024 не являются автоматической заменой без сопоставления состояний и требований."},{"h":"Структура и состояние поставки","p":"Механические свойства зависят от формы проката, толщины и термообработки; на массивной плите возможно перераспределение остаточных напряжений при снятии карманов."},{"h":"Особенности фрезерования","p":"В сравнении с мягким алюминием может формировать более дробную стружку, но условия налипания и устойчивости зависят от кромки. У тонких элементов важны зажим и прогиб."},{"h":"Режущий инструмент и стратегия","p":"Острая геометрия под Al, равномерные припуски, хорошее удаление стружки и контроль деформации после снятия зажима."},{"h":"Типовые проблемы","p":"Увод плоскостности плиты; задиры при наросте; деформация тонких стенок; повреждение слоя при небрежном захвате."},{"h":"Как проверить техпроцесс","p":"Проверить именно Д16Т, не Д16М; вид полуфабриката, состояние и качество поверхности; ожидаемую деформацию после черновой. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost4784","mat-author"],"linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-02","cat":"materials","title":"АМг6 — свойства и особенности фрезерования","subtitle":"Алюминиевые сплавы","quick":"Алюминиево-магниевый деформируемый сплав. АМг6 — относительно высоколегированный магнием деформируемый алюминиевый сплав, широко используемый в сварных и коррозионностойких конструкциях.","tags":["АМг6","АМг6","Алюминиевые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Алюминиево-магниевый деформируемый сплав. АМг6 — относительно высоколегированный магнием деформируемый алюминиевый сплав, широко используемый в сварных и коррозионностойких конструкциях."},{"h":"Структура и состояние поставки","p":"В отличие от Д16Т, прочность связана с твёрдым раствором и обработкой давлением, а не с тем же механизмом закалки и старения. После холодной деформации свойства могут отличаться."},{"h":"Особенности фрезерования","p":"Пластичный материал способен активно налипать и создавать длинную стружку; тепловые и зажимные деформации влияют на точность больших деталей."},{"h":"Режущий инструмент и стратегия","p":"Особое внимание удели чистой острой кромке, полированным канавкам, отведению вязкой стружки и предотвращению повторного резания."},{"h":"Типовые проблемы","p":"Нарост, матовые задиры, заусенцы на выходе и коробление тонких листов."},{"h":"Как проверить техпроцесс","p":"Состояние проката, толщина, зажим и потребность в сварке или коррозионной стойкости. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost4784","mat-author"],"linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-03","cat":"materials","title":"АМг3 — свойства и особенности фрезерования","subtitle":"Алюминиевые сплавы","quick":"Алюминиево-магниевый сплав средней степени легирования. Часто применяется в листах, корпусных и сварных конструкциях, где важны пластичность и устойчивость к коррозии.","tags":["АМг3","АМг3","Алюминиевые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Алюминиево-магниевый сплав средней степени легирования. Часто применяется в листах, корпусных и сварных конструкциях, где важны пластичность и устойчивость к коррозии."},{"h":"Структура и состояние поставки","p":"Мягкие или нагартованные состояния отличаются по жёсткости и формообразованию. Одно имя АМг3 не заменяет обозначение состояния поставки."},{"h":"Особенности фрезерования","p":"Для мягких листов характерны заусенцы, размазывание и чувствительность к опорам. Механические свойства после деформации отличаются от термически упрочняемых Al–Cu–Mg."},{"h":"Режущий инструмент и стратегия","p":"Не делай длинный вылет фрезы без необходимости; крепи большие тонкие поверхности с минимальной деформацией."},{"h":"Типовые проблемы","p":"Смазывание поверхности, длинная стружка, прогиб и зависимость размера от снятия прижимов."},{"h":"Как проверить техпроцесс","p":"Состояние листа, способ фиксации, открытые тонкие стенки, характер удаления стружки. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost4784","mat-author"],"linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-04","cat":"materials","title":"АД31 — свойства и особенности фрезерования","subtitle":"Алюминиевые сплавы","quick":"Деформируемый Al–Mg–Si для профилей. АД31 широко встречается как прессованный алюминиевый профиль. При термообработке и старении свойства меняются; сам по себе он не равен Д16 или В95.","tags":["АД31","АД31","Алюминиевые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Деформируемый Al–Mg–Si для профилей. АД31 широко встречается как прессованный алюминиевый профиль. При термообработке и старении свойства меняются; сам по себе он не равен Д16 или В95."},{"h":"Структура и состояние поставки","p":"В поставке встречаются разные состояния и варианты с различной прочностью, а на профилях могут быть тонкие полки и остаточные напряжения от прессования."},{"h":"Особенности фрезерования","p":"Чистовой проход по тонкой полке часто ограничен не мощностью шпинделя, а её прогибом и налипанием на режущей кромке."},{"h":"Режущий инструмент и стратегия","p":"Поддерживай полки, исключай сильный сжим профиля тисками, проверяй геометрию после разжима и острый инструмент под Al."},{"h":"Типовые проблемы","p":"Вмятины от крепежа, вибрация полки и разница измерений в закреплённом и свободном положении."},{"h":"Как проверить техпроцесс","p":"Конкретный профиль и состояние старения; толщина стенок, качество базы, наличие анодирования. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost4784","mat-author"],"linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-05","cat":"materials","title":"В95 — свойства и особенности фрезерования","subtitle":"Алюминиевые сплавы","quick":"Высокопрочный деформируемый Al–Zn–Mg–Cu сплав. В95 — высокопрочный алюминиевый сплав, применяемый в нагруженных деталях. Состав и обозначение состояния отличают его от Д16Т и АМг6.","tags":["В95","В95","Алюминиевые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Высокопрочный деформируемый Al–Zn–Mg–Cu сплав. В95 — высокопрочный алюминиевый сплав, применяемый в нагруженных деталях. Состав и обозначение состояния отличают его от Д16Т и АМг6."},{"h":"Структура и состояние поставки","p":"При различной закалке и искусственном старении прочность и напряжённое состояние отличаются; особенно важно не путать В95 и В95Т1."},{"h":"Особенности фрезерования","p":"Силовая нагрузка и износ инструмента могут оказаться выше, чем при фрезеровании мягкого алюминия; толстые плиты чувствительны к балансировке снятия."},{"h":"Режущий инструмент и стратегия","p":"Смотри состояние в сертификате, выбирай подходящую кромку и стратегию черновой, оставляй обоснованный припуск до чистовой после оценки коробления."},{"h":"Типовые проблемы","p":"Увод тонкого контура после черновой, микросколы от неравномерного остатка, изменение размера от нагрева."},{"h":"Как проверить техпроцесс","p":"Данные по состоянию, толщина плиты, требования к коррозии и остаточным напряжениям. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost4784","mat-author"],"linked":["mat-stress","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-06","cat":"materials","title":"АК12 (АЛ2) — свойства и особенности фрезерования","subtitle":"Литейные алюминиевые сплавы","quick":"Литейный алюминиево-кремниевый сплав, силумин. АК12 (в прежнем обозначении АЛ2) содержит существенную долю кремния; структура и форма кремниевых частиц делают поведение отличным от деформируемого алюминия.","tags":["АК12 (АЛ2)","АК12АЛ2","Литейные алюминиевые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Литейный алюминиево-кремниевый сплав, силумин. АК12 (в прежнем обозначении АЛ2) содержит существенную долю кремния; структура и форма кремниевых частиц делают поведение отличным от деформируемого алюминия."},{"h":"Структура и состояние поставки","p":"Свойства зависят от способа литья, модификации и пористости. Даже на одной отливке корка и сердцевина могут различаться."},{"h":"Особенности фрезерования","p":"Твёрдые частицы кремния ускоряют абразивный износ, а вскрытые поры нарушают гладкость финишной поверхности."},{"h":"Режущий инструмент и стратегия","p":"Для массовой обработки абразивных Al–Si возможны стойкие кромки и PCD по каталогу; учитывай литейную корку и локальные изменения припуска."},{"h":"Типовые проблемы","p":"Абразивный износ, непрогнозируемый скол на включениях, поры и раковины после чистовой."},{"h":"Как проверить техпроцесс","p":"Вид отливки, процент Si по документу, корка, пористость и требования к внешнему виду. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost1583","mat-author"],"linked":["mat-al-si","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-07","cat":"materials","title":"ВТ1-0 — свойства и особенности фрезерования","subtitle":"Титан и титановые сплавы","quick":"Технически чистый титан. ВТ1-0 — технический титан с высокой коррозионной стойкостью; не является аналогом по прочности сплава ВТ6.","tags":["ВТ1-0","ВТ10","Титан и титановые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Технически чистый титан. ВТ1-0 — технический титан с высокой коррозионной стойкостью; не является аналогом по прочности сплава ВТ6."},{"h":"Структура и состояние поставки","p":"Сплав не должен описываться как высокопрочный закалённый ВТ6. Состояние проката и деформации влияет на пластичность и твёрдость поверхности."},{"h":"Особенности фрезерования","p":"При сравнительно небольшой прочности сохраняются характерные для титана низкая теплопроводность, вязкость стружки и адгезия при контакте с кромкой."},{"h":"Режущий инструмент и стратегия","p":"Выбирай геометрию и охлаждение именно для технического титана; обеспечь эвакуацию стружки и достаточно жёсткую сборку."},{"h":"Типовые проблемы","p":"Налипание, задиры, нагрев кромки и местная деформация мягкого заготовочного слоя."},{"h":"Как проверить техпроцесс","p":"Марка ВТ1-0 vs ВТ6, состояние поставки, фактическая прочность, правила пожарной безопасности для стружки. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost19807","mat-author"],"linked":["mat-titanium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-08","cat":"materials","title":"ВТ6 — свойства и особенности фрезерования","subtitle":"Титан и титановые сплавы","quick":"Двухфазный титановый сплав Ti–Al–V. ВТ6 — титановый сплав альфа+бета; зарубежные Grade 5/Ti-6Al-4V близки по классу, но прямую замену утверждают только по стандарту и состоянию.","tags":["ВТ6","ВТ6","Титан и титановые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Двухфазный титановый сплав Ti–Al–V. ВТ6 — титановый сплав альфа+бета; зарубежные Grade 5/Ti-6Al-4V близки по классу, но прямую замену утверждают только по стандарту и состоянию."},{"h":"Структура и состояние поставки","p":"Закалка и старение либо другой заданный режим могут значительно менять прочность, а сложные детали после обработки способны иметь остаточные напряжения."},{"h":"Особенности фрезерования","p":"Сочетание высокой удельной прочности, неблагоприятного отвода тепла и упругой податливости тонких стенок затрудняет фрезерование."},{"h":"Режущий инструмент и стратегия","p":"Используй допустимые каталожные режимы для конкретного сплава, устойчивую фиксацию и контролируемое охлаждение; на сложной 3D-форме оцени локальное ae."},{"h":"Типовые проблемы","p":"Перегрев, ускоренный износ, скол, вибрации тонких стенок, риск воспламенения мелкой стружки."},{"h":"Как проверить техпроцесс","p":"Состояние и свойства, длина свободного вылета, условия СОЖ, процедура безопасной уборки стружки. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost19807","mat-author"],"linked":["mat-titanium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-09","cat":"materials","title":"ОТ4-1 — свойства и особенности фрезерования","subtitle":"Титан и титановые сплавы","quick":"Титановый сплав системы Ti–Al–Mn. ОТ4-1 относят к группе деформируемых титановых сплавов с алюминием и марганцем. Поведение не равно ВТ1-0 и ВТ6.","tags":["ОТ4-1","ОТ41","Титан и титановые сплавы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Титановый сплав системы Ti–Al–Mn. ОТ4-1 относят к группе деформируемых титановых сплавов с алюминием и марганцем. Поведение не равно ВТ1-0 и ВТ6."},{"h":"Структура и состояние поставки","p":"Формирование структуры и свойства определяются термомеханической обработкой; толщину и состояние полуфабриката проверяют отдельно."},{"h":"Особенности фрезерования","p":"Для резания остаются характерны тепло и адгезия титана, но конкретная прочность и механика стружки отличаются от ВТ6."},{"h":"Режущий инструмент и стратегия","p":"Не подставляй режимы ВТ6 «по умолчанию»; сверь марку, состояние, каталог инструмента и твёрдость."},{"h":"Типовые проблемы","p":"Налипание, термический износ, деформация тонких стенок, опасная мелкая стружка."},{"h":"Как проверить техпроцесс","p":"Сертификат ОТ4-1, состояние термообработки, режим охлаждения и безопасность обращения со стружкой. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost19807","mat-author"],"linked":["mat-titanium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-10","cat":"materials","title":"СЧ20 — свойства и особенности фрезерования","subtitle":"Чугуны","quick":"Серый чугун с пластинчатым графитом. Марка обозначает класс свойств чугуна с пластинчатым графитом, а не точный химический состав отливки. Часто встречается в корпусах и станочных деталях.","tags":["СЧ20","СЧ20","Чугуны","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Серый чугун с пластинчатым графитом. Марка обозначает класс свойств чугуна с пластинчатым графитом, а не точный химический состав отливки. Часто встречается в корпусах и станочных деталях."},{"h":"Структура и состояние поставки","p":"Структура металлической матрицы и качество литья меняют твёрдость; литейная корка, песок и включения отличаются от сердцевины."},{"h":"Особенности фрезерования","p":"При подходящих условиях образует короткую стружку, но корка и включения дают ударный контакт и абразивный износ."},{"h":"Режущий инструмент и стратегия","p":"Используй инструмент для группы K с учётом отливки; на первом проходе проверь корку и безопасность подхода, при чистовой — качество матрицы."},{"h":"Типовые проблемы","p":"Абразивный износ, локальный скол на песке, пыль и поры поверхности."},{"h":"Как проверить техпроцесс","p":"Марка и класс прочности, реальная твёрдость, размеры/припуск отливки, требования к удалению пыли. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost1412","mat-author"],"linked":["mat-cast-iron","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-11","cat":"materials","title":"СЧ25 — свойства и особенности фрезерования","subtitle":"Чугуны","quick":"Серый чугун более высокого класса прочности. СЧ25 — серый чугун с пластинчатым графитом, отличающийся классом механических требований от СЧ20. Не универсально «твёрже на 25%».","tags":["СЧ25","СЧ25","Чугуны","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Серый чугун более высокого класса прочности. СЧ25 — серый чугун с пластинчатым графитом, отличающийся классом механических требований от СЧ20. Не универсально «твёрже на 25%»."},{"h":"Структура и состояние поставки","p":"На фактическую обрабатываемость влияет металлическая матрица: перлитность, охлаждение и допустимые дефекты отливки."},{"h":"Особенности фрезерования","p":"При более прочной матрице средняя нагрузка может измениться, а характер износа всё ещё сильно определяется коркой и включениями."},{"h":"Режущий инструмент и стратегия","p":"Не используй только обозначение СЧ25 для назначения Vc; уточняй отливку, структуру и рекомендацию подгруппы ISO K."},{"h":"Типовые проблемы","p":"Износ по задней поверхности, повреждение зуба на твёрдом включении, нестабильная шероховатость."},{"h":"Как проверить техпроцесс","p":"СЧ20 vs СЧ25 в техдокументации, матрица, твёрдость, корка и заданная точность. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost1412","mat-author"],"linked":["mat-cast-iron","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-12","cat":"materials","title":"ВЧ50 — свойства и особенности фрезерования","subtitle":"Чугуны","quick":"Высокопрочный чугун с шаровидным графитом. ВЧ50 — высокопрочный чугун, где форма графита обычно шаровидная, а не пластинчатая, как у СЧ20/СЧ25. Марка связана с требованиями механических свойств.","tags":["ВЧ50","ВЧ50","Чугуны","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Высокопрочный чугун с шаровидным графитом. ВЧ50 — высокопрочный чугун, где форма графита обычно шаровидная, а не пластинчатая, как у СЧ20/СЧ25. Марка связана с требованиями механических свойств."},{"h":"Структура и состояние поставки","p":"Свойства зависят от ферритно-перлитной структуры, режима производства и возможной термообработки отливки."},{"h":"Особенности фрезерования","p":"Может давать другую стружку и другие силы по сравнению с серым чугуном; нельзя автоматически назначать режим СЧ20."},{"h":"Режущий инструмент и стратегия","p":"Сверь подгруппу группы K, твёрдость, матрицу и первый припуск; на конечной поверхности контролируй включения и поры."},{"h":"Типовые проблемы","p":"Рваная стружка и более высокие силы при определённой матрице, абразивный износ, прерывистый контакт."},{"h":"Как проверить техпроцесс","p":"Марка ВЧ50 и матрица, требования к отливке, HBW, характер стружки. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost7293","mat-author"],"linked":["mat-cast-iron","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-13","cat":"materials","title":"М1 — свойства и особенности фрезерования","subtitle":"Медь","quick":"Медь высокой чистоты. М1 — марка меди, часто используемая в электротехнических и теплопроводных деталях. Это не бронза и не латунь.","tags":["М1","М1","Медь","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Медь высокой чистоты. М1 — марка меди, часто используемая в электротехнических и теплопроводных деталях. Это не бронза и не латунь."},{"h":"Структура и состояние поставки","p":"Состояние после отжига или нагартовки существенно меняет пластичность и твёрдость, но материал остаётся относительно вязким и склонным к деформации."},{"h":"Особенности фрезерования","p":"При фрезеровании мягкой меди возможны длинная стружка, залипание и сильные заусенцы. Зажим легко повреждает чистовую поверхность."},{"h":"Режущий инструмент и стратегия","p":"Особое внимание к остроте режущей кромки, эвакуации стружки и исключению повреждения мягких баз зажимами."},{"h":"Типовые проблемы","p":"Заусенцы, смятая кромка, местные задиры и вмятины от оснастки."},{"h":"Как проверить техпроцесс","p":"Состояние поставки, требование к электропроводности, температура детали и способ закрепления. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost859","mat-author"],"linked":["mat-aluminium","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-14","cat":"materials","title":"Л63 — свойства и особенности фрезерования","subtitle":"Латуни","quick":"Двухкомпонентная латунь Cu–Zn. Л63 — деформируемая латунь с основой из меди и цинка, без того же назначения свинцовых добавок, что у ЛС59-1.","tags":["Л63","Л63","Латуни","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Двухкомпонентная латунь Cu–Zn. Л63 — деформируемая латунь с основой из меди и цинка, без того же назначения свинцовых добавок, что у ЛС59-1."},{"h":"Структура и состояние поставки","p":"После отжига или нагартовки свойства и форма стружки отличаются. Различия с ЛС59-1 важно учитывать до выбора инструмента."},{"h":"Особенности фрезерования","p":"Вязкость и склонность к заусенцам может быть выше, чем у автоматной свинцовой латуни; характер стружки зависит от состояния."},{"h":"Режущий инструмент и стратегия","p":"Используй подходящую геометрию для латуни; контролируй зажим и не оставляй тонкие упругие полки без поддержки."},{"h":"Типовые проблемы","p":"Заусенцы и вмятины на поверхности, вибрация тонких стенок, неравномерная стружка."},{"h":"Как проверить техпроцесс","p":"Уточнить Л63 vs ЛС59-1, состояние проката и требования к поверхности. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost15527","mat-author"],"linked":["mat-material-selection","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-15","cat":"materials","title":"ЛС59-1 — свойства и особенности фрезерования","subtitle":"Латуни","quick":"Свинцовая автоматная латунь. ЛС59-1 — медно-цинковая латунь со свинцом, который заметно меняет разрушение стружки. Сочетание букв ЛС важно: не путать с Л63.","tags":["ЛС59-1","ЛС591","Латуни","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Свинцовая автоматная латунь. ЛС59-1 — медно-цинковая латунь со свинцом, который заметно меняет разрушение стружки. Сочетание букв ЛС важно: не путать с Л63."},{"h":"Структура и состояние поставки","p":"После обработки давлением свойства отличаются, а присутствие свинца влияет на формирование короткой стружки и назначение материала."},{"h":"Особенности фрезерования","p":"В подходящих условиях часто даёт более короткую стружку и легче автоматизируется, чем многие бессвинцовые латуни; профиль и состояние влияют на результат."},{"h":"Режущий инструмент и стратегия","p":"Подбор геометрии для латуни отличается от мягкого алюминия. Соблюдай правила обращения со стружкой, содержащей свинец."},{"h":"Типовые проблемы","p":"Вкрапления и ухудшение поверхности при неподходящей кромке; вредная пыль и загрязнённая стружка."},{"h":"Как проверить техпроцесс","p":"Свинцовая ли марка, наличие требований к контакту с пищевой продукцией/питьевой водой, правила обращения с отходами. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost15527","mat-author"],"linked":["mat-material-selection","mat-iso-groups","mat-material-selection"]},{"id":"mat-grade-alloy-16","cat":"materials","title":"БрАЖ9-4 — свойства и особенности фрезерования","subtitle":"Бронзы","quick":"Алюминиево-железная безоловянная бронза. БрАЖ9-4 — бронза системы Cu–Al–Fe с повышенной прочностью в сравнении со многими мягкими медными сплавами. Не равнозначна ЛС59-1 по обрабатываемости.","tags":["БрАЖ9-4","БрАЖ94","Бронзы","марочник","материал","фреза"],"time":11,"actions":["Проверь точную марку, стандарт, состояние поставки и сертификат.","Уточни материал и состояние поверхности: литейная корка, прокат, упрочнение или старение.","Оцени способ крепления, местную толщину детали и эвакуацию стружки.","Выбери режущую геометрию и исходные режимы по каталогу для данного сплава, не по похожему названию."],"sections":[{"h":"Что за сплав и чем он отличается","p":"Алюминиево-железная безоловянная бронза. БрАЖ9-4 — бронза системы Cu–Al–Fe с повышенной прочностью в сравнении со многими мягкими медными сплавами. Не равнозначна ЛС59-1 по обрабатываемости."},{"h":"Структура и состояние поставки","p":"Структура и состояния после деформации либо термообработки существенно влияют на твёрдость, а у некоторых условий возможна неоднородность фаз."},{"h":"Особенности фрезерования","p":"По сравнению с мягкой медью нагрузка на кромку может быть выше, а устойчивый проход важнее максимальной скорости. Работа по корке также отличается."},{"h":"Режущий инструмент и стратегия","p":"Подбирай инструмент по группе и конкретной твёрдости; избегай скачков радиального зацепления в углах."},{"h":"Типовые проблемы","p":"Повышенный износ и локальные сколы при прерывистом входе; ухудшение поверхности из-за биения."},{"h":"Как проверить техпроцесс","p":"Состояние, стандарт, фактическая твёрдость, тип заготовки и конкретная оснастка. Данные ГОСТ подтверждают классификацию и состав, а технологические рекомендации являются объяснениями механизмов, не нормативными режимами резания."}],"sources":["grade-gost18175","mat-author"],"linked":["mat-material-selection","mat-iso-groups","mat-material-selection"]}];const gradeSet=new Set(d.materialGradeAtlas.map(g=>g.id));for(const g of grades)if(!gradeSet.has(g.id)){d.materialGradeAtlas.push(g);gradeSet.add(g.id)}const seen=new Set(d.articles.map(a=>a.id));for(const a of articles)if(!seen.has(a.id)){d.articles.push(a);seen.add(a.id);}})();